<script>
document.addEventListener('DOMContentLoaded', function () {
  var filter = document.querySelector('.cc-filter');
  var costCards = document.querySelector('.cc-cost-bottom');
  if (filter && costCards) filter.insertAdjacentElement('afterend', costCards);
  var action = document.querySelector('.cc-filter-action');
  if (!action || action.querySelector('[data-cost-reset]')) return;
  var reset = document.createElement('a');
  reset.className = 'btn btn-outline-secondary';
  reset.href = <?php echo json_encode(site_url('pos/reports/cost-control')); ?>;
  reset.setAttribute('data-cost-reset', '1');
  reset.innerHTML = '<i class="ri-refresh-line me-1"></i>Reset';
  action.appendChild(reset);
});
</script>
