ey($summary['production_cost'] ?? 0); ?></div><div class="cc-flow-meta"><?php echo number_format((int)($summary['production_batch_count'] ?? 0)); ?> batch posted<br>Bahan langsung: <?php echo $money($summary['material_usage_value'] ?? 0); ?></div></article><article class="cc-flow-card sales"><div class="cc-flow-step">06 · REALISASI</div><div class="cc-flow-name">HPP Terjual → Omzet</div><div class="cc-flow-value"><?php echo $money($hpp); ?></div><div class="cc-flow-meta">Omzet: <?php echo $money($netSales); ?><br>Laba kotor: <?php echo $money($grossProfit); ?></div></article></div></section>
  <div class="cc-dual"><section class="cc-panel"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Bahan Baku: masuk &amp; terpakai</h2><p class="cc-panel-sub">Membaca bahan dengan nilai tertinggi pada receipt PO dan input produksi.</p></div></div><div class="row g-0"><div class="col-md-6 border-end"><div class="px-3 pt-3"><strong class="small text-uppercase text-muted">Top masuk dari PO</strong></div><div class="cc-list"><?php $max = $maxValue($purchaseRows, 'purchase_value'); foreach ($purchaseRows as $row): ?><div class="cc-list-row"><div class="cc-list-main"><span><?php echo html_escape((string)($row['material_name'] ?? '-')); ?></span><span><?php echo $money($row['purchase_value'] ?? 0); ?></span></div><div class="cc-list-meta"><span><?php echo number_format((int)($row['receipt_count'] ?? 0)); ?> receipt</span><span>Masuk stok</span></div><div class="cc-list-bar"><span style="width:<?php echo $max > 0 ? min(100, (float)($row['purchase_value'] ?? 0) / $max * 100) : 0; ?>%"></span></div></div><?php endforeach; if (empty($purchaseRows)): ?><div class="cc-empty">Belum ada receipt bahan posted.</div><?php endif; ?></div></div><div class="col-md-6"><div class="px-3 pt-3"><strong class="small text-uppercase text-muted">Top dipakai produksi</strong></div><div class="cc-list"><?php $max = $maxValue($usageRows, 'usage_value'); foreach ($usageRows as $row): ?><div class="cc-list-row"><div class="cc-list-main"><span><?php echo html_escape((string)($row['material_name'] ?? '-')); ?></span><span><?php echo $money($row['usage_value'] ?? 0); ?></span></div><div class="cc-list-meta"><span><?php echo number_format((int)($row['batch_count'] ?? 0)); ?> batch</span><span>Masuk produksi</span></div><div class="cc-list-bar"><span style="width:<?php echo $max > 0 ? min(100, (float)($row['usage_value'] ?? 0) / $max * 100) : 0; ?>%"></span></div></div><?php endforeach; if (empty($usageRows)): ?><div class="cc-empty">Belum ada input bahan dari batch posted.</div><?php endif; ?></div></div></div></section><section class="cc-panel"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Stok bahan yang masih tertahan</h2><p class="cc-panel-sub">Saldo FIFO live: modal bahan yang belum menjadi biaya produksi atau HPP.</p></div></div><div class="cc-list"><?php $max = $maxValue($stockRows, 'stock_value'); foreach ($stockRows as $row): ?><div class="cc-list-row"><div class="cc-list-main"><span><?php echo html_escape((string)($row['material_name'] ?? '-')); ?></span><span><?php echo $money($row['stock_value'] ?? 0); ?></span></div><div class="cc-list-meta"><span><?php echo strtoupper((string)($row['location_scope'] ?? '')); ?> FIFO</span><span>Saldo live</span></div><div class="cc-list-bar"><span style="width:<?php echo $max > 0 ? min(100, (float)($row['stock_value'] ?? 0) / $max * 100) : 0; ?>%"></span></div></div><?php endforeach; if (empty($stockRows)): ?><div class="cc-empty">Tidak ada saldo lot bahan baku yang terbuka.</div><?php endif; ?></div></section></div>
  <div class="cc-dual"><section class="cc-panel"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Batch produksi terbaru</h2><p class="cc-panel-sub">Hanya batch posted agar biaya input sudah final.</p></div></div><div class="cc-table-wrap"><table class="table table-sm cc-table"><thead><tr><th>Batch</th><th>Produk antara</th><th>Lokasi</th><th class="text-end">Biaya input</th></tr></thead><tbody><?php foreach ($batchRows as $row): ?><tr><td><strong><?php echo html_escape((string)($row['batch_no'] ?? '-')); ?></strong><div class="pos-report-meta"><?php echo html_escape($date($row['batch_date'] ?? '')); ?></div></td><td><?php echo html_escape((string)($row['component_name'] ?? '-')); ?></td><td><?php echo html_escape((string)(($row['division_name'] ?? '') !== '' ? $row['division_name'] : ($row['location_type'] ?? '-'))); ?></td><td class="text-end"><strong><?php echo $money($row['total_input_cost'] ?? 0); ?></strong></td></tr><?php endforeach; if (empty($batchRows)): ?><tr><td colspan="4" class="cc-empty">Belum ada batch produksi posted pada periode ini.</td></tr><?php endif; ?></tbody></table></div></section><section class="cc-panel"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Waste dan pengeluaran non-belanja</h2><p class="cc-panel-sub">Waste dari adjustment posted. Kas tidak memasukkan purchase agar tidak dobel terhadap HPP.</p></div><span class="pos-report-badge danger"><?php echo $money($summary['waste_total'] ?? 0); ?> waste</span></div><div class="cc-list"><?php $max = $maxValue($shrinkageRows, 'shrinkage_value'); foreach ($shrinkageRows as $row): ?><div class="cc-list-row"><div class="cc-list-main"><span><?php echo html_escape((string)($row['material_name'] ?? '-')); ?></span><span class="text-danger"><?php echo $money($row['shrinkage_value'] ?? 0); ?></span></div><div class="cc-list-meta"><span>Waste, spoil, process loss, variance</span></div><div class="cc-list-bar"><span style="width:<?php echo $max > 0 ? min(100, (float)($row['shrinkage_value'] ?? 0) / $max * 100) : 0; ?>%"></span></div></div><?php endforeach; if (empty($shrinkageRows)): ?><div class="cc-empty">Tidak ada shrinkage posted pada periode ini.</div><?php endif; ?></div><div class="cc-table-wrap"><table class="table table-sm cc-table"><thead><tr><th>Kas non-belanja</th><th>Transaksi</th><th class="text-end">Kas keluar</th></tr></thead><tbody><?php foreach ($expenseRows as $row): ?><tr><td><strong><?php echo html_escape(str_replace('_', ' ', (string)($row['source_name'] ?? '-'))); ?></strong></td><td><?php echo number_format((int)($row['transaction_count'] ?? 0)); ?></td><td class="text-end"><strong><?php echo $money($row['expense_value'] ?? 0); ?></strong></td></tr><?php endforeach; if (empty($expenseRows)): ?><tr><td colspan="3" class="cc-empty">Belum ada pengeluaran non-belanja pada periode ini.</td></tr><?php endif; ?></tbody></table></div></section></div>
  <section class="cc-panel"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Kontrol Penyesuaian &amp; Beban Kas</h2><p class="cc-panel-sub">Penyesuaian minus mencakup waste, spoil, process loss, variance, dan adjustment minus komponen. Koreksi rekening POS dikeluarkan karena bukan beban.</p><div class="cc-adjustment-summary"><span class="cc-adjustment-chip">Bahan: <?php echo $money($summary['material_adjustment_minus'] ?? 0); ?> · <?php echo $pct($summary['material_adjustment_ratio_pct'] ?? 0); ?> dari bahan produksi</span><span class="cc-adjustment-chip">Komponen: <?php echo $money($summary['component_adjustment_minus'] ?? 0); ?> · <?php echo $pct($summary['component_adjustment_ratio_pct'] ?? 0); ?> dari biaya batch</span><span class="cc-adjustment-chip">Total: <?php echo $pct($summary['waste_ratio_pct'] ?? 0); ?> dari omzet</span></div></div><span class="pos-report-badge danger"><?php echo $money($summary['waste_total'] ?? 0); ?></span></div><details class="cc-detail"><summary>Rincian transaksi kas</summary><div class="cc-table-wrap"><table class="table table-sm cc-table"><thead><tr><th>Tanggal</th><th>Klasifikasi / Dokumen</th><th>Catatan</th><th class="text-end">Nilai</th></tr></thead><tbody><?php foreach ($expenseDetails as $row): ?><tr><td><?php echo html_escape($date($row['mutation_date'] ?? '')); ?></td><td><strong><?php echo html_escape((string)($row['source_name'] ?? '-')); ?></strong><div class="pos-report-meta"><?php echo html_escape((string)(($row['ref_no'] ?? '') !== '' ? $row['ref_no'] : ($row['mutation_no'] ?? '-'))); ?></div></td><td><?php echo html_escape((string)($row['notes'] ?? '-')); ?></td><td class="text-end"><strong><?php echo $money($row['amount'] ?? 0); ?></strong></td></tr><?php endforeach; if (empty($expenseDetails)): ?><tr><td colspan="4" class="cc-empty">Tidak ada rincian kas pada periode ini.</td></tr><?php endif; ?></tbody></table></div></details></section>
  <section class="cc-panel cc-margin-panel"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Margin Transaksi &amp; Modal Mengendap</h2><p class="cc-panel-sub">HPP memakai snapshot HPP live pada saat transaksi, termasuk extra, refund, dan koreksi defisit seperti laporan Penjualan. Stok mengendap adalah perubahan modal sejak awal periode.</p></div><span class="pos-report-badge success">HPP final transaksi</span></div><div class="cc-margin-grid"><article class="cc-margin-card"><div class="label">Omzet Bersih</div><div class="value"><?php echo $money($marginAnalysis['net_sales'] ?? 0); ?></div><div class="note">Dasar seluruh rasio margin</div></article><article class="cc-margin-card"><div class="label">HPP Final</div><div class="value"><?php echo $money($marginAnalysis['hpp_final'] ?? 0); ?></div><div class="note">Snapshot HPP live saat jual</div></article><article class="cc-margin-card"><div class="label">Laba Kotor</div><div class="value"><?php echo $money($marginAnalysis['gross_profit'] ?? 0); ?></div><div class="note">Margin <?php echo $pct($marginAnalysis['gross_margin_pct'] ?? 0); ?></div></article><article class="cc-margin-card"><div class="label">Setelah Beban Kas</div><div class="value <?php echo (float)($marginAnalysis['operating_contribution'] ?? 0) < 0 ? 'text-danger' : ''; ?>"><?php echo $money($marginAnalysis['operating_contribution'] ?? 0); ?></div><div class="note">Kontribusi <?php echo $pct($marginAnalysis['operating_contribution_pct'] ?? 0); ?></div></article><article class="cc-margin-card"><div class="label">Stok Bahan Awal</div><div class="value"><?php echo $money($marginAnalysis['material_opening'] ?? 0); ?></div><div class="note">Saldo awal bulan/periode</div></article><article class="cc-margin-card"><div class="label">Stok Bahan Akhir</div><div class="value"><?php echo $money($marginAnalysis['material_closing'] ?? 0); ?></div><div class="note">Saldo akhir bulan berjalan</div></article><article class="cc-margin-card"><div class="label">Modal Bahan Mengendap</div><div class="value <?php echo (float)($marginAnalysis['material_delta'] ?? 0) > 0 ? 'text-danger' : ''; ?>"><?php echo $money($marginAnalysis['material_delta'] ?? 0); ?></div><div class="note">Akhir dikurangi awal periode</div></article><article class="cc-margin-card"><div class="label">Modal Komponen Mengendap</div><div class="value <?php echo (float)($marginAnalysis['component_delta'] ?? 0) > 0 ? 'text-danger' : ''; ?>"><?php echo $money($marginAnalysis['component_delta'] ?? 0); ?></div><div class="note">Awal <?php echo $money($marginAnalysis['component_opening'] ?? 0); ?> · akhir <?php echo $money($marginAnalysis['component_closing'] ?? 0); ?></div></article></div><div class="cc-note m-3"><strong>Cara baca:</strong> angka modal mengendap positif berarti tambahan kas/modal masih berada di persediaan, bukan menjadi HPP atau biaya periode. Tab ini memakai angka penjualan perusahaan; filter divisi/lokasi tetap dipakai untuk stok dan operasional pada tab Alur Stok.</div></section>
  <section class="cc-panel cc-margin-panel"><div class="cc-insight"><div class="cc-insight-head"><h3 class="cc-insight-title">Pembacaan Manajerial</h3><span class="pos-report-badge secondary"><?php echo number_format((int)($marginAnalysis['period_days'] ?? 0)); ?> hari data</span></div><div class="cc-insight-grid"><article class="cc-insight-item"><strong>Ruang menutup beban kas <span class="score"><?php echo $pct($marginAnalysis['cash_coverage_pct'] ?? 0); ?></span></strong><span>Laba kotor dibanding beban kas non-belanja. Di atas 100% berarti margin kotor mampu menutup beban kas yang sudah diklasifikasikan.</span></article><article class="cc-insight-item"><strong>Tekanan modal stok <span class="score"><?php echo $pct($marginAnalysis['closing_capital_sales_pct'] ?? 0); ?></span></strong><span>Nilai stok bahan dan komponen akhir dibanding omzet. Setara sekitar <?php echo number_format((float)($marginAnalysis['stock_coverage_days'] ?? 0), 1, ',', '.'); ?> hari HPP periode.</span></article><article class="cc-insight-item"><strong>Modal baru tertahan <span class="score"><?php echo $pct($marginAnalysis['capital_delta_purchase_pct'] ?? 0); ?></span></strong><span>Perubahan modal stok dibanding receipt bahan periode ini. Positif berarti pembelian belum seluruhnya berubah menjadi produksi atau penjualan.</span></article><article class="cc-insight-item"><strong>Penyesuaian minus <span class="score"><?php echo $pct($marginAnalysis['adjustment_pct_sales'] ?? 0); ?></span></strong><span><?php echo $money($marginAnalysis['adjustment_total'] ?? 0); ?> dari bahan dan komponen. Pantau terpisah dari HPP agar waste dan selisih tidak tersembunyi.</span></article><article class="cc-insight-item"><strong>Margin setelah beban &amp; selisih <span class="score"><?php echo $pct($marginAnalysis['contribution_after_adjustment_pct'] ?? 0); ?></span></strong><span><?php echo $money($marginAnalysis['contribution_after_adjustment'] ?? 0); ?> adalah indikator konservatif setelah kas non-belanja dan penyesuaian minus.</span></article><article class="cc-insight-item"><strong>Modal persediaan total <span class="score"><?php echo $money($marginAnalysis['capital_delta'] ?? 0); ?></span></strong><span>Awal <?php echo $money($marginAnalysis['opening_capital'] ?? 0); ?> menjadi akhir <?php echo $money($marginAnalysis['closing_capital'] ?? 0); ?>. Ini bukan biaya, tetapi modal kerja yang perlu diawasi.</span></article></div></div></section>
  <section class="cc-panel cc-common-cost-panel cc-cost-bottom"><div class="cc-panel-head"><div><h2 class="cc-panel-title">Pengadaan Bahan &amp; Beban Operasional</h2><p class="cc-panel-sub">Bahan baku adalah modal masuk stok. Beban operasional mencakup Purchase non-bahan baku serta pengeluaran Payroll dan kas operasional lainnya.</p></div></div><div class="cc-cost-bridge"><article class="cc-cost-bridge-item"><div class="cc-cost-bridge-label">Pengadaan bahan baku</div><div class="cc-cost-bridge-value"><?php echo $money($materialPurchase); ?></div><div class="cc-cost-bridge-meta"><?php echo $pct($netSales > 0 ? $materialPurchase / $netSales * 100 : 0); ?> dari omzet · masuk persediaan, belum otomatis HPP</div></article><article class="cc-cost-bridge-item"><div class="cc-cost-bridge-label">Beban operasional</div><div class="cc-cost-bridge-value"><?php echo $money($operationalCash); ?></div><div class="cc-cost-bridge-meta"><?php echo $pct($netSales > 0 ? $operationalCash / $netSales * 100 : 0); ?> dari omzet · bahan pendukung, utilitas, payroll, dan biaya kas terklasifikasi</div><div class="cc-cost-breakdown"><?php foreach ($operationalRows as $row): ?><span><?php echo html_escape((string)($row['source_name'] ?? '-')); ?>: <?php echo $money($row['expense_value'] ?? 0); ?> (<?php echo number_format((int)($row['transaction_count'] ?? 0)); ?>)</span><?php endforeach; if (empty($operationalRows)): ?><span>Belum ada beban operasional terklasifikasi</span><?php endif; ?></div></article></div></section>
  <div class="cc-note"><strong>Interpretasi:</strong> receipt PO adalah modal bahan masuk. SR hanya memindahkan nilai tersebut ke divisi. Saldo FIFO gudang/divisi adalah modal yang masih tersimpan, biaya batch adalah modal yang sudah dikonversi, sedangkan HPP adalah bagian biaya yang sudah terealisasi karena produk terjual. Koreksi rekening pembayaran POS tidak dihitung sebagai beban kas karena hanya perpindahan pencatatan rekening. “Setelah beban kas” adalah indikator operasional, bukan laporan laba-rugi akrual final.</div>
</div>
